    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Insert();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

scwin.form_editForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.classInfoDiv1 = $c.util.getComponent('classInfoDiv1');
        scwin.classInfoDiv3 = $c.util.getComponent('classInfoDiv3');
        scwin.classInfoDiv4 = $c.util.getComponent('classInfoDiv4');
        scwin.classInfoDiv5 = $c.util.getComponent('classInfoDiv5');
        scwin.upd_formTxtfile = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_formTxtfile') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_formTxtfile"]');
        scwin.init_recvParam();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt50001.onpageload' });
    }
};

