scwin.tx_setRecentVersionInfo_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_setRecentVersionInfo_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_setRecentVersionInfo_xhr", unresolved: "action:self_submit:tx_setRecentVersionInfo_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name insert
 * @description insert 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function () {
    if (!await scwin.validate()) {
        return;
    }
    if (($c.util.getComponent('ipt_formEngNm').getValue() === null ? '' : String($c.util.getComponent('ipt_formEngNm').getValue())) === '') {
        $c.util.getComponent("ipt_formEngNm").setValue("N/A");
    }
    if ($c.util.getComponent('slc_wrtrptMaindocTpCd').getValue() !== "1") {
        $c.util.getComponent("slc_rsnClssCd").setValue("");
        $c.util.getComponent("slc_formUpclssCd").setValue("");
    }
    const formUpclssCd = $c.util.getComponent('slc_formUpclssCd').getValue();
    const rsnClssCd = $c.util.getComponent('slc_rsnClssCd').getValue();
    if ((formUpclssCd === "01" && rsnClssCd === "040") || (formUpclssCd === "01" && rsnClssCd === "041") || (formUpclssCd === "09" && rsnClssCd === "006") || (formUpclssCd === "09" && rsnClssCd === "009")) {
        if ($c.util.getComponent('slc_inqdisclsTpCd').getValue() !== "A") {
            $c.util.getComponent("slc_inqdisclsAnsTpCd").setValue("");
        }
    } else {
        $c.util.getComponent("slc_inqdisclsTpCd").setValue("");
        $c.util.getComponent("slc_inqdisclsContnTpCd").setValue("");
        $c.util.getComponent("slc_inqdisclsAnsTpCd").setValue("");
    }
    $c.util.getComponent('dma_InsertReq').set('method', "createForm");
    scwin.form_editForm.action = "/filing/updateForm.do";
    scwin.form_editForm.target = "hiddenFrame";
    await scwin.tx_fn_Insert();
};

/**
 * @method
 * @name validate
 * @description validate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validate = async function () {
    if (String(($c.util.getComponent("ipt_formCd") || { getValue: function () { return ''; } }).getValue() || '').length !== 5) { await $c.win.alert("서식코드는 다섯자리수입니다."); ($c.util.getComponent("ipt_formCd") && $c.util.getComponent("ipt_formCd").setFocus ? $c.util.getComponent("ipt_formCd").setFocus() : ($c.util.getComponent("ipt_formCd") && $c.util.getComponent("ipt_formCd").focus ? $c.util.getComponent("ipt_formCd").focus() : void 0)); return false; }
    if (String(($c.util.getComponent("ipt_formKorNm") || { getValue: function () { return ''; } }).getValue() || '').replace(/\s/g, '') === '') { await $c.win.alert("서식명을 입력해 주세요."); ($c.util.getComponent("ipt_formKorNm") && $c.util.getComponent("ipt_formKorNm").setFocus ? $c.util.getComponent("ipt_formKorNm").setFocus() : ($c.util.getComponent("ipt_formKorNm") && $c.util.getComponent("ipt_formKorNm").focus ? $c.util.getComponent("ipt_formKorNm").focus() : void 0)); return false; }
    if (String(($c.util.getComponent("cal_strtDd") || { getValue: function () { return ''; } }).getValue() || '').replace(/\s/g, '') === '') { await $c.win.alert("서식사용개시일자를 입력해 주세요."); ($c.util.getComponent("cal_strtDd") && $c.util.getComponent("cal_strtDd").setFocus ? $c.util.getComponent("cal_strtDd").setFocus() : ($c.util.getComponent("cal_strtDd") && $c.util.getComponent("cal_strtDd").focus ? $c.util.getComponent("cal_strtDd").focus() : void 0)); return false; }
    return true;
};

/**
 * @method
 * @name changeRsnTpInfo
 * @description change Rsn Tp Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.changeRsnTpInfo = async function () {
    await scwin.findRsnClasses();
    scwin.changeInqdisclsInfo();
};

/**
 * @method
 * @name changeInqdisclsInfo
 * @description change Inqdiscls Info 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeInqdisclsInfo = function () {
    const formUpclssCd = $c.util.getComponent('slc_formUpclssCd').getValue();
    const rsnClssCd = $c.util.getComponent('slc_rsnClssCd').getValue();
    if ((formUpclssCd === "01" && rsnClssCd === "040") || (formUpclssCd === "01" && rsnClssCd === "041") || (formUpclssCd === "09" && rsnClssCd === "006") || (formUpclssCd === "09" && rsnClssCd === "009")) {
        scwin.classInfoDiv3.setStyle("display", "block");
        scwin.changeInqdisclsInfo2();
    } else {
        scwin.classInfoDiv3.setStyle("display", "none");
        scwin.classInfoDiv4.setStyle("display", "none");
    }
};

/**
 * @method
 * @name changeInqdisclsInfo2
 * @description change Inqdiscls Info2 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeInqdisclsInfo2 = function () {
    if ($c.util.getComponent('slc_inqdisclsTpCd').getValue() === "A") {
        scwin.classInfoDiv4.setStyle("display", "block");
    } else {
        scwin.classInfoDiv4.setStyle("display", "none");
    }
};

/**
 * @method
 * @name list
 * @description list 처리
 * @returns {void}
 * @hidden N
 */
scwin.list = function () {
    $c.win.moveUrl("/filing/form.do");
};

/**
 * @method
 * @name findRsnClasses
 * @description find Rsn Classes 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findRsnClasses = async function () {
    scwin.form_editForm.action = "/filing/updateForm.do";
    $c.util.getComponent('dma_InsertReq').set('method', "findReasonClasses");
    scwin.dataDiv = "reasonClass";
    await scwin.tx_findRsnClasses_xhr();
};

/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} responseText responseText
 * @returns {void}
 * @hidden N
 */
scwin.onCompleteResponse = function (responseText) {
    ($c.util.getComponent("document.all.select_" + scwin.dataDiv) && $c.util.getComponent("document.all.select_" + scwin.dataDiv).setValue) ? $c.util.getComponent("document.all.select_" + scwin.dataDiv).setValue(responseText) : (($c.util.getComponent("document.all.select_" + scwin.dataDiv) && $c.util.getComponent("document.all.select_" + scwin.dataDiv).setText) ? $c.util.getComponent("document.all.select_" + scwin.dataDiv).setText(responseText) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "document.all.select_" + scwin.dataDiv), void (responseText)));
};

/**
 * @method
 * @name setFormVer
 * @description set Form Ver 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setFormVer = async function (obj) {
    if (obj.getValue().length < 5) {
        return;
    }
    $c.util.getComponent('dma_InsertReq').set('method', "findFormVers");
    scwin.form_editForm.action = "/filing/updateForm.do";
    const formVerHtml = await scwin.tx_setFormVer_xhr();
    $c.util.getComponent('formVerDiv').innerHTML = formVerHtml;
    await scwin.setRecentVersionInfo(obj.getValue());
};

/**
 * @method
 * @name setRecentVersionInfo
 * @description set Recent Version Info 처리
 * @param {String} formCd formCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setRecentVersionInfo = async function (formCd) {
    scwin.form_editForm.action = "/filing/findForm.do";
    $c.util.getComponent('dma_InsertReq').set('method', "findRecentVersionFormInfo");
    const jsonText = await scwin.tx_setRecentVersionInfo_xhr();
    const json = new JSON(jsonText);
    const preFormVer = json.getValue("formVer");
    if (preFormVer !== "") {
        $c.util.getComponent('dma_InsertReq').set('preFormVer', preFormVer);
        $c.util.getComponent('txt_comment').setLabel("(이전버전 : " + preFormVer + ") ");
        for (let i = 0; i < document.editForm.elements.length; i++) {
            const ename = document.editForm.elements[i].name;
            if (ename === "formVer" || ename === "endDd" || ename === "repFormVerYn") {
                continue;
            }
            const value = json.getValue(ename);
            if (editForm[ename] !== null && value !== "") {
                $c.util.getComponent("editForm." + ename).setValue(value);
            }
            if (ename === "engFormYn" || ename === "listFormYn") {
                if (value === "Y") {
                    editForm[ename][0].checked = true;
                }
                if (value === "N") {
                    editForm[ename][1].checked = true;
                }
            }
            if (ename === "disclsTitleChgPosblYn") {
                $c.util.getComponent('dma_InsertReq').set('hidDisclsTitleChgPosblYn', value);
            }
            if (ename === "formUpclssCd") {
                await scwin.changeRsnTpInfo();
            }
        }
    } else {
        $c.util.getComponent('dma_InsertReq').set('preFormVer', "");
        $c.util.getComponent('txt_comment').setLabel("(신규) ");
        $c.util.getComponent("ipt_formKorNm").setValue("");
        $c.util.getComponent("ipt_formEngNm").setValue("");
        $c.util.getComponent("ipt_engFormCd").setValue("");
        $c.util.getComponent("ipt_engFormVer").setValue("");
        $c.util.getComponent("cal_strtDd").setValue("");
        $c.util.getComponent("txa_remk").setValue("");
    }
    scwin.displayInformation($c.util.getComponent('slc_wrtrptMaindocTpCd'));
    scwin.changeInqdisclsInfo();
    if ($c.util.getComponent('dma_InsertReq').get('hidDisclsTitleChgPosblYn') === "Y") {
        $c.util.getComponent("rd_disclsTitleChgPosblYn").setValue("Y");
    } else {
        $c.util.getComponent("rd_disclsTitleChgPosblYn").setValue("N");
    }
};

/**
 * @method
 * @name displayInformation
 * @description display Information 처리
 * @param {*} mainDocObj mainDocObj
 * @returns {void}
 * @hidden N
 */
scwin.displayInformation = function (mainDocObj) {
    let display = "block";
    if (mainDocObj.getValue() !== "1") {
        display = "none";
    }
    scwin.classInfoDiv1.setStyle("display", display);
    scwin.classInfoDiv3.setStyle("display", display);
    scwin.classInfoDiv4.setStyle("display", display);
    scwin.classInfoDiv5.setStyle("display", display);
    if (mainDocObj.getValue() === "1") {
        $c.util.getComponent('txt_text1').setLabel("상장신청서구분");
        ($c.util.getComponent('text2') && $c.util.getComponent('text2').setValue) ? $c.util.getComponent('text2').setValue("상장") : (($c.util.getComponent('text2') && $c.util.getComponent('text2').setText) ? $c.util.getComponent('text2').setText("상장") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'text2'), void ("상장")));
    } else {
        $c.util.getComponent('txt_text1').setLabel("공시비공시구분");
        ($c.util.getComponent('text2') && $c.util.getComponent('text2').setValue) ? $c.util.getComponent('text2').setValue("비공시") : (($c.util.getComponent('text2') && $c.util.getComponent('text2').setText) ? $c.util.getComponent('text2').setText("비공시") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'text2'), void ("비공시")));
    }
};

/**
 * @method
